44	const PROCESSING_FEE = 5;
45	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
46	
47	const BASE_PREMIUMS = {
48	  sword: 100,
49	  amulet: 60,
50	  staff: 80,
51	  potion: 40,
52	  rune: 25,
53	  moonstone: 25,
54	} as const satisfies Record<string, number>;
55	
56	export type InsurableItemType = keyof typeof BASE_PREMIUMS;
57	
58	const basePremiumForType = (type: string): number =>
59	  BASE_PREMIUMS[type as InsurableItemType];
60	
61	const BLOCK_SIZE = 3;
62	const BLOCK_PREMIUM = 60;
63	
64	const groupByType = (items: Item[]): Map<string, Item[]> => {
65	  const groups = new Map<string, Item[]>();
66	  for (const item of items) {
67	    const alike = groups.get(item.type);
68	    if (alike) alike.push(item);
69	    else groups.set(item.type, [item]);
70	  }
71	  return groups;
72	};
73	
74	// Items of one type, quoted together. A group of exactly 3 forms a building
75	// block and is offered at a flat base premium; any other size is priced per
76	// item. "Alike" means the same item type — 2 runes + 1 moonstone is two
77	// groups, so neither is a block.
78	type AlikeGroup = [type: string, items: Item[]];
79	
80	const isBuildingBlock = ([, items]: AlikeGroup): boolean =>
81	  items.length === BLOCK_SIZE;
82	
83	const basePremiumForGroup = (group: AlikeGroup): number => {
84	  const [type, items] = group;
85	  return isBuildingBlock(group)
86	    ? BLOCK_PREMIUM
87	    : items.length * basePremiumForType(type);
88	};
89	
90	const sumBasePremiums = (items: Item[]): number =>
91	  [...groupByType(items)].reduce(
92	    (total, group) => total + basePremiumForGroup(group),
93	    0,
94	  );
95	
96	const CURSE_SURCHARGE_RATE = 0.5;
97	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
98	const HIGH_ENCHANTMENT_THRESHOLD = 5;
99	
100	const isHighlyEnchanted = (item: Item): boolean =>
101	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
102	
103	// Item-specific modifiers apply to the base premium of the affected item, not
104	// to the policy total.
105	const surchargeRateForItem = (item: Item): number =>
106	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
107	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
108	
109	const sumItemSurcharges = (items: Item[]): number =>
110	  items.reduce(
111	    (total, item) =>
112	      total + basePremiumForType(item.type) * surchargeRateForItem(item),
113	    0,
114	  );
115	
116	// Premiums are rounded up, in the MHPCO's favour; only the final premium is
117	// rounded, intermediate amounts stay fractional.
118	const roundInMHPCOsFavour = Math.ceil;
119	
120	const quotePremium = (items: Item[]): number => {
121	  const basePremium = sumBasePremiums(items);
122	  const itemSurcharges = sumItemSurcharges(items);
123	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
124	  return roundInMHPCOsFavour(
125	    basePremium + itemSurcharges + firstInsuranceSurcharge + PROCESSING_FEE,
126	  );
127	};
128	
129	const runStep = (step: Step): QuoteResult | ClaimResult => {
130	  switch (step.op) {
131	    case "quote":
132	      return { premium: quotePremium(step.items) };
133	    case "claim":
134	      throw new Error("claim steps are not supported yet");
135	  }
136	};
137	
138	export const runScenario = (scenario: Scenario): ScenarioResults => ({
139	  results: scenario.steps.map(runStep),
140	});
